python3 -c "
import pandas as pd
df = pd.read_csv('/app/dataset/readings.csv')
st020 = df[df['station_id'] == 'ST020'].sort_values('timestamp').reset_index(drop=True)
# check other PM10 stations
pm10_sids = df[df['pollutant'] == 'PM10']['station_id'].unique()
for sid in pm10_sids:
    if sid == 'ST020':
        continue
    other = df[df['station_id'] == sid].sort_values('timestamp').reset_index(drop=True)
    # check correlation and matches at different lags
    for lag in range(-4, 5):
        if lag == 0:
            corr = st020['current_reading'].corr(other['current_reading'])
        elif lag > 0:
            corr = st020['current_reading'].iloc[lag:].reset_index(drop=True).corr(other['current_reading'].iloc[:-lag].reset_index(drop=True))
        else:
            corr = st020['current_reading'].iloc[:lag].reset_index(drop=True).corr(other['current_reading'].iloc[-lag:].reset_index(drop=True))
        if corr > 0.95:
            print(f'ST020 and {sid} have correlation {corr:.6f} at lag {lag}!')
"

