import pandas as pd
df = pd.read_csv('/app/dataset/readings.csv')
sids = df['station_id'].unique()

# Check all pairs of stations for high correlation at any lag
for i, s1 in enumerate(sids):
    for j, s2 in enumerate(sids):
        if i >= j:
            continue
        p1 = df[df['station_id'] == s1]['pollutant'].iloc[0]
        p2 = df[df['station_id'] == s2]['pollutant'].iloc[0]
        if p1 != p2:
            continue

        df1 = df[df['station_id'] == s1].sort_values('timestamp').reset_index(drop=True)
        df2 = df[df['station_id'] == s2].sort_values('timestamp').reset_index(drop=True)

        for lag in range(-4, 5):
            if lag == 0:
                corr = df1['current_reading'].corr(df2['current_reading'])
            elif lag > 0:
                corr = df1['current_reading'].iloc[lag:].reset_index(drop=True).corr(df2['current_reading'].iloc[:-lag].reset_index(drop=True))
            else:
                corr = df1['current_reading'].iloc[:lag].reset_index(drop=True).corr(df2['current_reading'].iloc[-lag:].reset_index(drop=True))

