def answer() -> set[str]:
    # Identified faulty stations:
    # 1. ST020: Broadly follows local patterns but with a different rhythm (clock shift / 1-step lag).
    # 2. ST051: Highly correlated with peers (plausible point-by-point) but has muted swings (extremely low standard deviation ratio of ~0.55).
    # 3. ST060: Appears ordinary in aggregate (mean/std align with peers) but remaining deviations (residuals) correlate strongly with rain accumulation (~ -0.65).
    return {"ST020", "ST051", "ST060"}

if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(list(answer()), f)
